head.script:
// 테스트 설명, 유효성 값 설정
//  - 본 샘플(_2) 담당 : HTML 태그 해석 여부 (escape / embeddedInput)
//  - 기본 동작은 _1, inputType=spinner 는 _3 에서 다룬다.
scwin.tData = {
    "description" : "[column > P > customFormatter]<br/>Column 이 편집 상태가 아닐때 표시될 Column 값을 반환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "inputType='textarea', escape=true 인 Column 은 HTML 태그가 해석되지 않고 문자 그대로 표시됩니다.",
        "inputType='text', 'textImage' 이고 embeddedInput=true 인 Column 은 HTML 태그가 해석되지 않고 문자 그대로 표시됩니다.",
        "inputType='textarea', embeddedInput=true 인 Column 은 customFormatter 속성이 무시됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (escape=true 로 시작)
    con_escape.setValue("2");
    con_embeddedInput.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 사용자 정의 함수 : 포맷된 Column 값을 빨간색 span 태그로 감싸서 반환
scwin.fmtHtml = function (data, formattedData, rowIndex, columnIndex) {
    return "<span style='color:#d0021b'>" + formattedData + "</span>";
};



// comp 생성
//  - 세 Body Column(text / textImage / textarea) 모두 customFormatter="scwin.fmtHtml" 고정
//  - con_escape 는 textarea Column 에만, con_embeddedInput 은 세 Column 모두에 적용 (미설정은 속성 자체를 넣지 않음)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 상품명(text), 상태(textImage), 비고(textarea) Column 에 customFormatter=scwin.fmtHtml (빨간색 span 태그로 감싼 값 반환) 고정\n[전제] escape 는 비고(textarea) Column 에만 (미설정 시 기본값 true), embeddedInput 은 세 Column 모두에 적용\n[확인] 재생성 직후 결과창의 Row 별 표시값 (태그 문자 그대로 / 태그 해석 / 원본값)"', '', 'label1');

    // 조건 설정 (gdl_boolean 은 getText 로 읽음)
    let cEscape = con_escape.getText();
    let cEmbeddedInput = con_embeddedInput.getText();

    let attrEmbedded = (cEmbeddedInput === '') ? '' : ' embeddedInput="' + cEmbeddedInput + '"';
    let attrEscape = (cEscape === '') ? '' : ' escape="' + cEscape + '"';

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ctextimg" name="ctextimg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cmemo" name="cmemo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "ctext" : "노트북", "ctextimg" : "정상", "cmemo" : "2층 창고 보관" },
        { "ctext" : "모니터", "ctextimg" : "지연", "cmemo" : "입고 검수 대기" },
        { "ctext" : "키보드", "ctextimg" : "정상", "cmemo" : "20% 할인 적용" }
    ], false);

    // 실제 서빙되는 아이콘 이미지 (textImage 가 화면에 보이도록)
    let imgSrc = "/cm/images/contents/btn_folder.png";

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="상품명(text)"></w2:column>';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column2" value="상태(textImage)"></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column3" value="비고(textarea)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="ctext" value="" customFormatter="scwin.fmtHtml"' + attrEmbedded + '></w2:column>';
    strTarget += '<w2:column width="220" style="" inputType="textImage" id="ctextimg" value="" viewType="icon" imageSrc="' + imgSrc + '" customFormatter="scwin.fmtHtml"' + attrEmbedded + '></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="textarea" id="cmemo" value="" customFormatter="scwin.fmtHtml"' + attrEscape + attrEmbedded + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1, 2, 3 : 전체 Row 의 Column 별 표시값
    setTimeout(function () {
        for (let i = 0; i < dlt_bind.getRowCount(); i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " " + scwin.getCellStr(i, 0) + " / " + scwin.getCellStr(i, 1) + " / " + scwin.getCellStr(i, 2));
        }
    }, 100);
}



// Cell 표시값 : 입력 요소(embeddedInput)면 value, 아니면 textContent. span 태그가 해석되어 요소로 존재하면 (태그 해석) 표기
scwin.getCellStr = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_" + colIndex + "']");
    if (!td) {
        return "Cell 없음";
    }
    let input = td.querySelector("input, textarea");
    let str = input ? "'" + input.value + "'" : "'" + td.textContent.trim() + "'";
    if (td.querySelector("span[style*='color']")) {
        str += "(태그 해석)";
    }
    return str;
}
